import {gunzipSync} from 'node:zlib';import{mkdirSync,existsSync,writeFileSync}from'node:fs';import{resolve,dirname,sep}from'node:path';import{spawn}from'node:child_process';
const root=resolve('.oweleaf-app');if(!existsSync(root)){const tree=JSON.parse(gunzipSync(Buffer.from('','base64')).toString());for(const [name,data]of Object.entries(tree)){const p=resolve(root,name);if(!p.startsWith(root+sep))throw Error('Unsafe source path');mkdirSync(dirname(p),{recursive:true});writeFileSync(p,Buffer.from(data,'base64'));}}
const test=process.argv.includes('--test'),demo=process.argv.includes('--demo');const p=spawn(process.execPath,test?['--test','test/*.test.js']:['src/server.js'],{cwd:root,stdio:'inherit',env:{...process.env,...(demo?{FARTHING_MOCK:'1'}:{})}});p.on('exit',code=>process.exitCode=code??1);
